[{"type":"text","text":"# 鑻忎綇鎴縂 (zhi2-web-admin) 鏈湴 nginx 閮ㄧ讲 鈥斺€?root 鎸囧悜鏈」鐩?dist锛坴ite outDir = 浠撳簱鏍?dist锛?
# 浠ｇ悊瀵归綈 env/.env.test 鐨?VITE_APP_PROXY_ADDRESS锛堣嫃浣忔埧 G 娴嬭瘯鐜缃戝叧锛?
# 璇存槑锛?v2.0/evaluation/ 璧版湰鍦?zhi2-evaluation锛堝惈 stdEvaluation 鏂版ā鍧楋級锛屽叾浣欒蛋娴嬭瘯鐜缃戝叧
server {
    listen 8101;
    server_name localhost;
    root D:/repository/鑻忎綇鎴縂/worktrees/dist;
    index index.html;
    charset utf-8;
    client_max_body_size 100m;

    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host unlimited.g.h5.admin.web.v2.suzhufang.shiqu.suzhou.test.zhi.com;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_connect_timeout 60s;
    proxy_send_timeout 120s;
    proxy_read_timeout 120s;

    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|xlsx|json)$ {
        expires 7d;
        add_header Cache-Control "public" always;
        access_log off;
        try_files $uri =404;
    }
    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
