[{"type":"text","text":"// Render Axure prototype pages to PNG for visual reference.
const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

const PROTO = 'C:\\Users\\Administrator\\Downloads\\鑻忎綇鎴?鐗╀笟鏍囧噯鍖栬瘎浠穃\鑻忎綇鎴?鐗╀笟鏍囧噯鍖栬瘎浠?;
const OUT = path.join(__dirname, '..', '..', 'artifacts', 'proto-shots');
fs.mkdirSync(OUT, { recursive: true });

const pages = process.argv.slice(2).length ? process.argv.slice(2) : [
  '棣栭〉.html', '璇勪环鏍囧噯.html', '鐗╀笟鏈嶅姟绛夌骇.html', '鐗╀笟鑷煡璁板綍.html',
  '琛楅晣妫€鏌ヨ褰?html', '鍖哄幙妫€鏌ヨ褰?html', '甯傜骇妫€鏌ヨ褰?html',
  '鏁存敼閫氱煡涔?html', '璇勪环鎶ュ憡缂栧埗.html', '璇勪环鎶ュ憡.html', '鐗╀笟鏍囧噯鍖栬瘎浠?10_22_鏀?html'
];

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });
  for (const p of pages) {
    const url = 'file:///' + path.join(PROTO, p).replace(/\\/g, '/');
    try {
      await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 });
      await page.waitForTimeout(1500);
