[{"type":"text","text":"/**
 * 閫氳繃 nginx UI HTTP API 娉ㄥ唽/鏇存柊骞跺惎鐢ㄣ€岃嫃浣忔埧G銆嶇珯鐐癸紝鐒跺悗 reload nginx銆? * 鐢ㄩ€旓細婊¤冻椤圭洰瑙勫垯銆屽墠绔瀯寤轰骇鐗╀竴寰嬬敤鏈湴 nginx UI 閮ㄧ讲銆嶏紝绔欑偣鐢?nginx UI 绠＄悊锛? *       涓嶆墜鍐?sites-enabled 鏂囦欢銆? *
 * 鐢ㄦ硶锛歯ode e2e/std-evaluation/tools/nginx-ui-deploy.cjs [confFile]
 *   confFile 榛樿 D:\evalrun\suzhufangg-site.conf
 * 鐜鍙橀噺锛歂GINX_UI_URL(榛樿 http://127.0.0.1:9000)銆丯GINX_UI_DB(榛樿 D:\nginx-ui\database.db)
 *           SITE_NAME(榛樿 鑻忎綇鎴縂)
 *
 * 鎺ュ彛锛堟湰鏈?nginx UI 瀹炴祴锛夛細
 *   GET  /api/sites/{name}        鏌ヨ绔欑偣锛堣繑鍥?config / path / status锛? *   POST /api/sites/{name}        body {content}锛?*浠呮柊寤?*锛涙枃浠跺凡瀛樺湪鏃惰繑鍥? *                                 500 {"scope":"site","code":50001,"message":"destination file already exists"}
 *   POST /api/sites/{name}/enable | /disable
 *   POST /api/nginx/reload
 *   娉ㄦ剰锛歯ginx UI v2 娌℃湁銆屾洿鏂板唴瀹广€嶆帴鍙ｏ紝鍥犳宸插瓨鍦ㄧ殑绔欑偣鏀逛负鐩存帴鍐欏叆鍏跺彈绠℃枃浠? *        锛堣矾寰勫彇鑷?GET 杩斿洖鐨?path锛夛紝鍐?enable + reload銆? *
 * 閴存潈锛歯ginx UI 鐧诲綍瀵嗙爜鏈満鏈煡锛堝簱涓?bcrypt 涓庡凡鐭ュ彛浠や笉鍖归厤锛夛紝鏀逛负澶嶇敤鍏?database.db 涓? *       鏈繃鏈熺殑 auth_tokens JWT锛堝彧璇绘煡璇紝涓嶆敼搴擄級銆? */
const fs = require('fs')
const path = require('path')
const { DatabaseSync } = require('node:sqlite')

const UI = process.env.NGINX_UI_URL || 'http://127.0.0.1:9000'
const DB = process.env.NGINX_UI_DB || 'D:\\nginx-ui\\database.db'
const SITE = process.env.SITE_NAME || '鑻忎綇鎴縂'
const confFile = process.argv[2] || 'D:\\evalrun\\suzhufangg-site.conf'

function getToken() {
  const db = new DatabaseSync(DB, { readOnly: true })
  const rows = db.prepare("SELECT token FROM auth_tokens WHERE token <> '' ORDER BY expired_at DESC").all()
  db.close()
  if (!rows.length) throw new Error('nginx UI 搴撲腑娌℃湁鍙敤 token锛岃鍏堝湪 nginx UI 椤甸潰鐧诲綍涓€娆?)
  return rows[0].token
}

async function api(token, method, url, body) {
  const res = await fetch(UI + url, {
    method,
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined
  })
  const text = await res.text()
  let json = null
  try {
    json = JSON.parse(text)
  } catch (e) {}
  return { status: res.status, json, text }
}

const brief = (r) => (r.json ? JSON.stringify(r.json) : r.text).slice(0, 160)

;(async () => {
  const token = getToken()
  const content = fs.readFileSync(path.resolve(confFile), 'utf8').replace(/^\uFEFF/, '')
  const name = encodeURIComponent(SITE)

  const existing = await api(token, 'GET', `/api/sites/${name}`)
  if (existing.status === 200 && existing.json && existing.json.path) {
    // 绔欑偣宸插瓨鍦細nginx UI v2 鏃犳洿鏂版帴鍙ｏ紝鐩存帴鍐欏彈绠℃枃浠讹紙鏃?BOM锛?    const target = existing.json.path
    fs.writeFileSync(target, content, { encoding: 'utf8' })
    console.log(`鏇存柊绔欑偣 ${SITE} 閰嶇疆锛?{target}锛?{Buffer.byteLength(content)} 瀛楄妭锛塦)
  } else {
    const created = await api(token, 'POST', `/api/sites/${name}`, { content })
    console.log(`鏂板缓绔欑偣 ${SITE}: HTTP ${created.status} ${brief(created)}`)
    if (created.status >= 300) process.exit(1)
  }

  const en = await api(token, 'POST', `/api/sites/${name}/enable`)
  console.log(`鍚敤绔欑偣 ${SITE}: HTTP ${en.status} ${brief(en)}`)
  if (en.status >= 300) process.exit(1)

  const reload = await api(token, 'POST', '/api/nginx/reload')
  console.log(`nginx reload: HTTP ${reload.status} ${brief(reload)}`)

  const one = await api(token, 'GET', `/api/sites/${name}`)
  const cfg = (one.json && one.json.config) || ''
  const ok = cfg.includes('/v2.0/evaluation/')
  console.log(`鏍￠獙锛?{ok ? '宸插寘鍚湰鍦板悗绔矾鐢? : '缂哄皯鏈湴鍚庣璺敱'}锛涙枃浠?${(one.json && one.json.path) || '?'}锛涚姸鎬?${(one.json && one.json.status) || '?'}`)
  process.exit(ok ? 0 : 1)
})().catch((e) => {
  console.error('FATAL', e.message)
  process.exit(1)
})
"}]

[{"type":"text","text":"// Log into the deployed app (nginx 8101) and screenshot evaluation pages.
const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

const BASE = 'http://127.0.0.1:8101';
