  ['stdEvalDistrictCheckRecord', '鍖哄幙妫€鏌ヨ褰?],
  ['stdEvalCityCheckRecord', '甯傜骇妫€鏌ヨ褰?],
  ['stdEvalRectification', '鏁存敼閫氱煡涔?],
  ['stdEvalReportPrepare', '璇勪环鎶ュ憡缂栧埗'],
  ['stdEvalReport', '璇勪环鎶ュ憡'],
  ['stdEvalAreaReportPrepare', '鍖哄煙璇勪环鎶ュ憡缂栧埗'],
