      await page.screenshot({ path: path.join(OUT, route + '.png'), fullPage: false });
      const t = await page.locator('.el-table').count();
      console.log('OK', route, 'tables=' + t, 'url=' + page.url().replace(BASE, ''));
    } catch (e) {
