// Bug 6071 verification: capture 工单分类 list on deployed site (nginx 8101).
const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

const BASE = 'http://127.0.0.1:8101';
const PASS = fs.readFileSync(path.join(process.env.TEMP, 'e2e_pass.txt'), 'utf8').trim();
const USER = process.env.E2E_USER || 'zsbase';
const OUT = path.join(__dirname, '..', '..', 'artifacts', 'bug6071');
fs.mkdirSync(OUT, { recursive: true });

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await ctx.newPage();
  page.on('console', m => { if (m.type() === 'error') console.log('  [console.error]', m.text().slice(0, 200)); });
  page.on('response', async r => {
    if (r.url().includes('category') && r.status() >= 400) console.log('  [resp]', r.status(), r.url().slice(0, 140));
  });

  await page.goto(BASE + '/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(1500);
  if ((await page.locator('input[type="password"]').count()) > 0) {
    await page.locator('input[placeholder*="用户名"], input[placeholder*="账号"]').first().fill(USER);
    await page.locator('input[type="password"]').first().fill(PASS);
    const cap = page.locator('input[placeholder*="验证码"]');
    if (await cap.count()) await cap.fill(process.env.E2E_CAPTCHA || '1234');
    await Promise.all([
      page.waitForResponse(r => r.url().includes('userLogin'), { timeout: 30000 }).catch(() => null),
      page.locator('.login-button, button:has-text("登录")').first().click()
    ]);
    await page.waitForTimeout(3000);
  }
  console.log('after login url:', page.url());

  // 工单分类 page route
  const route = 'property/workOrder/category';
  await page.evaluate((r) => { location.hash = '#/' + r; }, route);
  await page.waitForTimeout(2000);
