// Bug 6071 verification: login, fetch menu routers, find 工单分类 route, screenshot list.
const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

const BASE = 'http://127.0.0.1:8101';
const PASS = fs.readFileSync(path.join(process.env.TEMP, 'e2e_pass.txt'), 'utf8').trim();
const USER = process.env.E2E_USER || 'zsbase';
const OUT = path.join(__dirname, '..', '..', 'artifacts', 'bug6071');
fs.mkdirSync(OUT, { recursive: true });

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await ctx.newPage();
  page.on('console', m => { if (m.type() === 'error') console.log('  [console.error]', m.text().slice(0, 160)); });

  await page.goto(BASE + '/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(2500);
  if (page.url().includes('/login') || (await page.locator('input[type="password"]').count()) > 0) {
    const inputs = page.locator('input');
    await inputs.nth(0).fill(USER);
    await inputs.nth(1).fill(PASS);
    if ((await inputs.count()) > 2) await inputs.nth(2).fill('1234');
    await page.locator('button:has-text("登")').first().click();
    await page.waitForTimeout(4000);
  }
  console.log('after login url:', page.url());

  const routers = await page.evaluate(async () => {
    const token = localStorage.getItem('token') || sessionStorage.getItem('token');
    const res = await fetch('/v2.0/system/menu/getRouters', { headers: { Authorization: 'Bearer ' + token } });
    return await res.json();
  });
  const found = [];
  function walk(items, parents) {
    for (const it of items || []) {
      const c = it.component || '';
      const p = it.path || '';
      const m = it.meta || {};
      if (/workOrder|category/i.test(c + p) || /工单/.test(m.title || '')) {
        found.push({ title: m.title, path: p, component: c, parent: parents.join('/') });
      }
      if (it.children) walk(it.children, parents.concat(m.title || p));
    }
  }
  walk((routers.data) || routers.rows || [], []);
  console.log('ROUTES', JSON.stringify(found, null, 1));
  fs.writeFileSync(path.join(OUT, 'routes.json'), JSON.stringify(found, null, 2));
  await browser.close();
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });

