// Dump child menu tree under 项目管理 to find 工单分类 route chain.
const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

const BASE = 'http://127.0.0.1:8101';
const PASS = fs.readFileSync(path.join(process.env.TEMP, 'e2e_pass.txt'), 'utf8').trim();
const OUT = path.join(__dirname, '..', '..', 'artifacts', 'bug6071');
fs.mkdirSync(OUT, { recursive: true });

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto(BASE + '/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(2500);
  const ins = page.locator('input');
  await ins.nth(0).fill('zsbase');
  await ins.nth(1).fill(PASS);
  if ((await ins.count()) > 2) await ins.nth(2).fill('1234');
  const t = page.locator('.login-button').first();
  if (await t.count()) await t.click(); else await ins.nth(2).press('Enter');
  await page.waitForTimeout(5000);

  const menus = await page.evaluate(async () => {
    const token = sessionStorage.getItem('Admin-Token');
    const res = await fetch('/v2.0/system/menu/list', { headers: { Authorization: token, token_type: 'user' } });
    return (await res.json()).data || [];
  });
  const byId = new Map(menus.map(m => [String(m.menuId), m]));

  function chainOf(m) {
    const c = [];
    let cur = m;
    while (cur) { c.unshift({ id: cur.menuId, name: cur.menuName, path: cur.path, comp: cur.component, type: cur.menuType }); cur = byId.get(String(cur.parentId)); }
    return c;
  }
  const targets = menus.filter(m => /分类|工单/.test(m.menuName || ''));
  const out = targets.map(m => ({ chain: chainOf(m) }));
  console.log(JSON.stringify(out, null, 1));
  fs.writeFileSync(path.join(OUT, 'targets.json'), JSON.stringify(out, null, 1));
  await browser.close();
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });

