// Bug 6071 verification: login, read vuex permission routes, find 工单分类, navigate & screenshot.
const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

const BASE = 'http://127.0.0.1:8101';
const PASS = fs.readFileSync(path.join(process.env.TEMP, 'e2e_pass.txt'), 'utf8').trim();
const OUT = path.join(__dirname, '..', '..', 'artifacts', 'bug6071');
fs.mkdirSync(OUT, { recursive: true });

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await ctx.newPage();
  page.on('console', m => { if (m.type() === 'error') console.log('  [cerr]', m.text().slice(0, 160)); });
  page.on('response', async r => {
    const u = r.url();
    if (u.includes('/property/workOrder/category')) console.log('  [api]', r.status(), u.replace(BASE, '').slice(0, 160));
  });

  await page.goto(BASE + '/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(2500);
  if ((await page.locator('input[type="password"]').count()) > 0) {
    const ins = page.locator('input');
    await ins.nth(0).fill('zsbase');
    await ins.nth(1).fill(PASS);
    if ((await ins.count()) > 2) await ins.nth(2).fill('1234');
    const t = page.locator('.login-button').first();
    if (await t.count()) await t.click(); else await ins.nth(2).press('Enter');
    await page.waitForTimeout(6000);
  }
  console.log('after login url:', page.url());

  // read vuex permission state
  const info = await page.evaluate(() => {
    const out = { hasApp: false, routes: [] };
    const app = document.querySelector('#app');
    const vm = app && app.__vue__;
    if (vm && vm.$store) {
      out.hasApp = true;
      const perm = vm.$store.state.permission || {};
      const walk = (arr, prefix) => {
        for (const r of arr || []) {
          const full = (prefix + '/' + (r.path || '')).replace(/\/+/g, '/');
          out.routes.push({ path: full, name: r.name, title: r.meta && r.meta.title, comp: typeof r.component === 'function' ? 'fn' : (r.component && (r.component.name || r.component.__file)) || '' });
          if (r.children) walk(r.children, full);
        }
      };
      walk(perm.routes || [], '');
      walk(perm.navbarRouters || [], '');
      out.keys = Object.keys(perm);
    }
    return out;
  });
  console.log('HAS_APP', info.hasApp, 'permKeys', JSON.stringify(info.keys));
  const hit = (info.routes || []).filter(r => /工单分类|workOrder|category/i.test((r.title || '') + r.path + r.comp));
  console.log('HIT_ROUTES', JSON.stringify(hit.slice(0, 20), null, 1));
  fs.writeFileSync(path.join(OUT, 'perm-routes.json'), JSON.stringify(info, null, 1));

  await browser.close();
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });

