// Bug 6071 verification: use page.goto to the route directly (not just hash), then filter 报修.
const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

const BASE = 'http://127.0.0.1:8101';
const PASS = fs.readFileSync(path.join(process.env.TEMP, 'e2e_pass.txt'), 'utf8').trim();
const OUT = path.join(__dirname, '..', '..', 'artifacts', 'bug6071');
fs.mkdirSync(OUT, { recursive: true });
const ROUTE = 'property/workOrder/workOrder/category';

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await ctx.newPage();
  page.on('response', async r => {
    const u = r.url();
    if (u.includes('/property/workOrder/category/list')) console.log('  [api]', r.status(), u.replace(BASE, '').slice(0, 220));
  });

  // login first
  await page.goto(BASE + '/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(2500);
  if ((await page.locator('input[type="password"]').count()) > 0) {
    const ins = page.locator('input');
    await ins.nth(0).fill('zsbase');
    await ins.nth(1).fill(PASS);
    if ((await ins.count()) > 2) await ins.nth(2).fill('1234');
    const t = page.locator('.login-button').first();
    if (await t.count()) await t.click(); else await ins.nth(2).press('Enter');
    await page.waitForTimeout(6000);
  }
  console.log('after login', page.url());

  // Direct route URL with query (deep link) - use goto so onMounted + permission guard run cleanly
  const url = BASE + '/#/' + ROUTE;
  await page.goto(url, { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(5000);
  await page.locator('.el-loading-mask').first().waitFor({ state: 'detached', timeout: 25000 }).catch(() => {});
  await page.waitForTimeout(2000);
  console.log('url after goto', page.url());

  // Dismiss driver/popover overlays via JS
  const dismiss = async () => {
    await page.evaluate(() => {
      document.querySelectorAll('.driver-overlay, .driver-popover, .driver-highlighted-element, .v-modal').forEach(el => el.remove());
      document.querySelectorAll('.el-popover').forEach(el => { el.style.display = 'none'; });
    });
  };
  await dismiss();
  await page.waitForTimeout(500);

  // Set the search form's categoryType select programmatically via Vue if possible, else via DOM
  const setViaVue = await page.evaluate(() => {
    const formEls = Array.from(document.querySelectorAll('.list-container'));
    // find a vue instance exposing queryParams
    function findVm(node) {
      let el = node;
      while (el) {
        if (el.__vue__) return el.__vue__;
        el = el.parentElement;
      }
      return null;
    }
    const root = formEls[0] && formEls[0].__vue__;
    if (!root) return { ok: false };
    // climb to page component with queryParams + getList
    let vm = root;
    let guard = 0;
    while (vm && guard++ < 12) {
      if (vm.queryParams && typeof vm.getList === 'function') break;
      vm = vm.$parent;
    }
    if (!vm || !vm.queryParams) return { ok: false, keys: root && Object.keys(root.$data || {}) };
    vm.queryParams.categoryType = '2';
    vm.handleQuery && vm.handleQuery();
    if (typeof vm.getList === 'function') vm.getList();
    return { ok: true, qp: JSON.stringify(vm.queryParams) };
  });
  console.log('setViaVue', JSON.stringify(setViaVue));
  await page.waitForTimeout(3000);
  await page.locator('.el-loading-mask').first().waitFor({ state: 'detached', timeout: 20000 }).catch(() => {});
  await page.waitForTimeout(2000);
  await dismiss();

  await page.screenshot({ path: path.join(OUT, 'list-repair.png'), fullPage: false });
  const rows = await page.locator('.el-table__body-wrapper tbody tr').evaluateAll(trs =>
    trs.map(tr => Array.from(tr.querySelectorAll('td')).map(td => td.innerText.trim()))
  );
  console.log('rows=' + rows.length);
  console.log('ROWS', JSON.stringify(rows, null, 1));
  fs.writeFileSync(path.join(OUT, 'rows-repair.json'), JSON.stringify(rows, null, 1));
  await browser.close();
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });

